// src/create/submission-lock.ts
function createSubmissionLock() {
  let locked = false;
  return {
    get locked() {
      return locked;
    },
    tryAcquire() {
      if (locked) return false;
      locked = true;
      return true;
    },
    release() {
      locked = false;
    }
  };
}

